package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.ConvergenceChecker;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.FunctionEvaluationException;
import org.apache.commons.math3.optim.univariate.GoalType;
import org.apache.commons.math3.optim.univariate.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.UnivariateRealPointValuePair;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for MultiStartUnivariateRealOptimizer.optimize(FUNC, GoalType, double, double)
 */
public class MultiStartUnivariateRealOptimizer_optimize_TriageGen1Test {

    private MultiStartUnivariateRealOptimizer optimizer;
    private BaseUnivariateRealOptimizer<UnivariateRealFunction> baseOptimizer;

    @Before
    public void setUp() {
        // Using a simple BrentOptimizer as the base optimizer for testing
        baseOptimizer = new org.apache.commons.math3.optim.univariate.BrentOptimizer(1e-10, 1e-14);
        // 5 starts, fixed seed for reproducibility
        optimizer = new MultiStartUnivariateRealOptimizer(baseOptimizer, 5, new JDKRandomGenerator(42));
    }

    /**
     * Tests optimization for finding a minimum of a simple quadratic function: f(x) = (x-2)^2 + 5
     * The minimum is at x=2, value=5.
     */
    @Test
    public void testOptimizeMinimizeQuadratic() throws FunctionEvaluationException {
        UnivariateRealFunction f = x -> Math.pow(x - 2.0, 2) + 5.0;
        double min = 0.0;
        double max = 5.0;

        UnivariateRealPointValuePair result = optimizer.optimize(f, GoalType.MINIMIZE, min, max);

        assertNotNull(result);
        assertEquals(2.0, result.getPoint(), 1e-5);
        assertEquals(5.0, result.getValue(), 1e-5);
    }

    /**
     * Tests optimization for finding a maximum of a simple quadratic function: f(x) = -(x-3)^2 + 10
     * The maximum is at x=3, value=10.
     */
    @Test
    public void testOptimizeMaximizeQuadratic() throws FunctionEvaluationException {
        UnivariateRealFunction f = x -> -Math.pow(x - 3.0, 2) + 10.0;
        double min = 0.0;
        double max = 6.0;

        UnivariateRealPointValuePair result = optimizer.optimize(f, GoalType.MAXIMIZE, min, max);

        assertNotNull(result);
        assertEquals(3.0, result.getPoint(), 1e-5);
        assertEquals(10.0, result.getValue(), 1e-5);
    }

    /**
     * Tests the behavior when the function throws a FunctionEvaluationException.
     * This ensures the exception propagates through the optimize method.
     */
    @Test(expected = FunctionEvaluationException.class)
    public void testOptimizeThrowsFunctionEvaluationException() throws FunctionEvaluationException {
        UnivariateRealFunction f = x -> {
            if (x > 2.0) {
                throw new FunctionEvaluationException(new RuntimeException("Evaluation error"));
            }
            return x;
        };
        // This range includes values > 2.0
        optimizer.optimize(f, GoalType.MINIMIZE, 0.0, 5.0);
    }

    /**
     * Tests optimization with a very narrow range where the optimum is at the boundary.
     */
    @Test
    public void testOptimizeBoundary() throws FunctionEvaluationException {
        // f(x) = x, minimum is at min
        UnivariateRealFunction f = x -> x;
        double min = 1.0;
        double max = 2.0;

        UnivariateRealPointValuePair result = optimizer.optimize(f, GoalType.MINIMIZE, min, max);

        assertNotNull(result);
        assertEquals(min, result.getPoint(), 1e-5);
        assertEquals(min, result.getValue(), 1e-5);
    }

    /**
     * Tests that the internal call to the 5-parameter optimize method (with startValue) 
     * is triggered correctly via the 4-parameter method.
     * The 4-parameter method calculates startValue = min + 0.5 * (max + min).
     */
    @Test
    public void testOptimizeInternalStartValueLogic() throws FunctionEvaluationException {
        // Function with a very sharp peak so that the starting point matters
        // If startValue logic is wrong, it might miss the peak.
        // For min=0, max=10, startValue should be 0 + 0.5*(10+0) = 5.
        UnivariateRealFunction f = x -> Math.exp(-Math.pow(x - 5.0, 2));
        double min = 0.0;
        double max = 10.0;

        UnivariateRealPointValuePair result = optimizer.optimize(f, GoalType.MAXIMIZE, min, max);

        assertNotNull(result);
        assertEquals(5.0, result.getPoint(), 1e-5);
        assertEquals(1.0, result.getValue(), 1e-5);
    }
}
